    const canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;const ctx=canvas.getContext('2d');ctx.drawImage(img,sx,sy,side,side,0,0,512,512);
    return canvas.toDataURL('image/jpeg',.82)
