function attemptLogin(){
  if(!localUserReady()){toast('No user data found — create a user first');renderCreateUser();return}
  applyStoredClientName();if(!progress||progress.clientId!==plan.client.id)progress=newProgress();ensureProgressExtras();write();finishOnboardingToApp();
}
function starterSessions(count){
  const ex=(name,sets,a,b,focus)=>({name,sets,repMin:a,repMax:b,focus});
  const fullA={id:'full-a',dayLabel:'Day 1',name:'Full Body A',subtitle:'Chest · Back · Legs',exercises:[ex('Incline Dumbbell Press',4,6,10,'Upper chest'),ex('Lat Pulldown',4,8,12,'Lat width'),ex('Leg Press',4,8,12,'Quads'),ex('Lateral Raise',3,12,18,'Shoulders'),ex('Dumbbell Curl',3,8,12,'Biceps')]};
  const fullB={id:'full-b',dayLabel:'Day 2',name:'Full Body B',subtitle:'Back · Chest · Posterior chain',exercises:[ex('Romanian Deadlift',4,6,10,'Hamstrings / glutes'),ex('Seated Cable Row',4,8,12,'Mid-back'),ex('Flat Dumbbell Press',4,8,12,'Chest'),ex('Cable Triceps Pushdown',3,10,15,'Triceps'),ex('Standing Calf Raise',4,10,15,'Calves')]};
  const push={id:'push',dayLabel:'Push',name:'Push',subtitle:'Chest · Shoulders · Triceps',exercises:[ex('Incline Dumbbell Press',4,6,10,'Upper chest'),ex('Flat Dumbbell Press',3,8,12,'Chest'),ex('Seated Shoulder Press',3,8,12,'Shoulders'),ex('Lateral Raise',3,12,18,'Side delts'),ex('Cable Triceps Pushdown',3,10,15,'Triceps')]};
  const pull={id:'pull',dayLabel:'Pull',name:'Pull',subtitle:'Lats · Back · Biceps',exercises:[ex('Lat Pulldown',4,8,12,'Lat width'),ex('Seated Cable Row',4,8,12,'Mid-back'),ex('Chest Supported Row',3,8,12,'Upper back'),ex('Face Pull',3,12,18,'Rear delts'),ex('Dumbbell Curl',3,8,12,'Biceps')]};
  const legs={id:'legs',dayLabel:'Legs',name:'Legs',subtitle:'Quads · Hamstrings · Calves',exercises:[ex('Leg Press',4,8,12,'Quads'),ex('Romanian Deadlift',4,6,10,'Hamstrings / glutes'),ex('Bulgarian Split Squat',3,8,12,'Quads / glutes'),ex('Leg Curl',3,10,15,'Hamstrings'),ex('Standing Calf Raise',4,10,15,'Calves')]};
  const upperA={...push,id:'upper-a',dayLabel:'Upper A',name:'Upper A',subtitle:'Chest · Lats · Shoulders'};
  const lowerA={...legs,id:'lower-a',dayLabel:'Lower A',name:'Lower A'};
  const upperB={...pull,id:'upper-b',dayLabel:'Upper B',name:'Upper B',subtitle:'Back · Chest · Arms',exercises:[ex('Lat Pulldown',4,8,12,'Lat width'),ex('Flat Dumbbell Press',4,8,12,'Chest'),ex('Seated Cable Row',3,8,12,'Mid-back'),ex('Lateral Raise',3,12,18,'Shoulders'),ex('Dumbbell Curl',3,8,12,'Biceps'),ex('Cable Triceps Pushdown',3,10,15,'Triceps')]};
  const lowerB={...legs,id:'lower-b',dayLabel:'Lower B',name:'Lower B',exercises:[ex('Romanian Deadlift',4,6,10,'Hamstrings / glutes'),ex('Leg Press',4,10,15,'Quads'),ex('Walking Lunge',3,10,14,'Quads / glutes'),ex('Leg Curl',3,10,15,'Hamstrings'),ex('Standing Calf Raise',4,10,15,'Calves')]};
  if(count<=2)return [fullA,fullB];if(count===3)return [push,pull,legs];if(count===4)return [upperA,lowerA,upperB,lowerB];return [push,pull,legs,upperB,lowerB]
}
function createTargets(weight){const protein=Math.round(weight*2),fat=Math.round(weight*.8),calories=Math.round((weight*33+250)/50)*50,carbs=Math.max(0,Math.round((calories-protein*4-fat*9)/4));return {calories,protein,carbs,fat}}
function updateCreateTargetPreview(){const w=Number(document.getElementById('newWeight')?.value)||70,t=createTargets(w),box=document.getElementById('createTargetPreview');if(box)box.innerHTML=`<b>Starter daily targets</b><div class="create-target-row"><div><span>Calories</span><strong>${t.calories}</strong></div><div><span>Protein</span><strong>${t.protein} g</strong></div><div><span>Carbs</span><strong>${t.carbs} g</strong></div><div><span>Fat</span><strong>${t.fat} g</strong></div></div>`}
