function renderTour(dir=1){
  const s=slides[tour],card=document.getElementById('tourCard');
  card.classList.remove('slide-in-right','slide-in-left'); void card.offsetWidth;
  card.classList.add(dir>=0?'slide-in-right':'slide-in-left');
  const last=tour===slides.length-1;
  card.innerHTML=`<div class="eyebrow">Onboarding · ${tour+1} of ${slides.length}</div><h2>${s.title}</h2><p class="tour-copy">${s.copy}</p>${s.body()}<div class="tour-actions">${tour?'<button class="btn secondary" onclick="moveTour(-1)">Back</button>':''}<button id="tourContinue" class="btn primary" ${(s.needsPlan&&!plan)||(tour===0&&!clientNameValue())?'disabled':''} onclick="nextTour()">${last?'Enter Gain Focus':'Continue'}</button></div><div class="onboard-foot">${tour===0?'The plan JSON is read-only inside the app.':'You can change the client plan later from Settings.'}</div>`;
  document.getElementById('tourDots').innerHTML=slides.map((_,i)=>`<i class="${i===tour?'on':''}"></i>`).join('');
}
function moveTour(d){tour=clamp(tour+d,0,slides.length-1);renderTour(d)}
function nextTour(){
  if(tour===0&&!clientNameValue()){const i=document.getElementById('clientNameStart');if(i){i.focus();i.animate([{transform:'translateX(0)'},{transform:'translateX(-4px)'},{transform:'translateX(4px)'},{transform:'translateX(0)'}],{duration:240})}return}
  if(slides[tour].needsPlan&&!plan)return;
  if(tour<slides.length-1){moveTour(1);return}
  if(progress)progress.tutorialComplete=true;write();finishOnboardingToApp();
}

document.getElementById('planFile').addEventListener('change',e=>{
  const f=e.target.files[0];if(!f)return;
  const r=new FileReader();
  r.onload=()=>{try{const x=JSON.parse(r.result);if(!validPlan(x))throw new Error('invalid');const changed=!plan||plan.client.id!==x.client.id;plan=x;applyStoredClientName();if(changed||!progress||progress.clientId!==plan.client.id)progress=newProgress();write();toast('Client plan imported');onboardMode==='login'?renderLoginGate():renderTour(1)}catch{alert('That JSON is not a valid Gain Focus client plan.')}};
  r.readAsText(f);e.target.value='';
});

document.getElementById('progressFile').addEventListener('change',e=>{
  const f=e.target.files[0];if(!f||!plan)return;
  const r=new FileReader();
  r.onload=()=>{try{const x=JSON.parse(r.result);if(!progressCompatible(x))throw new Error('mismatch');progress=x;progress.appVersion=APP_VERSION;ensureProgressExtras();if(typeof ensureWeeklyReviewIds==='function')ensureWeeklyReviewIds();write();toast('Progress restored');onboardMode==='login'?renderLoginGate():renderTour(1)}catch(e){console.error(e);alert('That progress JSON does not belong to this client plan.')}};
  r.readAsText(f);e.target.value='';
});

