function renderModuleSafe(tabId,label,fn){
  try{fn()}
  catch(e){
    console.error(`Gain Focus ${label} render failed`,e);
    const el=document.getElementById(tabId);
    if(el)el.innerHTML=`<div class="card glass hero"><div class="eyebrow">${esc(label)}</div><h2>Couldn’t load this section.</h2><p class="muted">Gain Focus isolated a rendering error so the rest of the app can keep working. Reload once; if it persists, replace the app build rather than your client data.</p></div>`;
  }
}
