const EXERCISE_STOCK={bench:'data:image/webp;base64,',incline:'data:image/webp;base64,',shoulder:'data:image/webp;base64,',lateral:'data:image/webp;base64,',pulldown:'data:image/webp;base64,',row:'data:image/webp;base64,',triceps:'data:image/webp;base64,',squat:'data:image/webp;base64,',hinge:'data:image/webp;base64,'};

function exerciseStockKey(e){
  const n=`${e?.name||''} ${e?.focus||''}`.toLowerCase().replace(/[^a-z0-9+\- ]+/g,' ');
  if(/incline/.test(n)&&/(press|bench|smith|barbell|machine)/.test(n))return'incline';
  if(/seated shoulder press|shoulder press|overhead press|military press/.test(n))return'shoulder';
  if(/lateral raise|rear-delt cable fly|rear delt cable fly|rear delt fly|reverse pec deck|face pull/.test(n))return'lateral';
  if(/lat pulldown|pull-down|straight-arm pulldown|straight arm pulldown|neutral-grip lat pulldown|neutral grip lat pulldown/.test(n))return'pulldown';
  if(/seated cable row|chest supported row|chest-supported row|cable row/.test(n))return'row';
  if(/tricep|pushdown|rope pushdown|overhead cable extension|skull crusher/.test(n))return'triceps';
  if(/romanian deadlift|\brdl\b|deadlift|leg curl|hamstring curl|back extension/.test(n))return'hinge';
  if(/barbell squat|back squat|front squat|leg press|walking lunge|reverse lunge|bulgarian split squat|split squat|standing calf raise|seated calf raise|calf raise|hack squat|\bsquat\b/.test(n))return'squat';
  if(/flat dumbbell press|bench press|chest press|dumbbell press|smith press|barbell press|machine chest press/.test(n))return'bench';
  if(/dumbbell curl|hammer curl|barbell curl|ez curl|preacher curl|cable curl|incline curl|dumbbell shrug|barbell shrug|shrug|\bcurl\b/.test(n))return'lateral';
  return'';
}
function exerciseStockFallbackKey(e){
  const s=`${e?.name||''} ${e?.focus||''}`.toLowerCase();
  if(/trap|shrug/.test(s))return 'shoulder';
  if(/rear delt|rear-delt|side delt|lateral|raise|curl|bicep/.test(s))return 'lateral';
  if(/tricep/.test(s))return 'triceps';
  if(/lat|pull/.test(s))return 'pulldown';
  if(/row|mid-back|upper back/.test(s))return 'row';
  if(/hamstring|glute|deadlift|rdl|curl/.test(s))return 'hinge';
  if(/quad|calf|lunge|split squat|squat|leg press|leg extension/.test(s))return 'squat';
  if(/chest|pec|press|fly/.test(s))return /incline|upper chest|clavicular/.test(s)?'incline':'bench';
  return '';
}
