  if(!samples.length)return {palette:[[0,0,0]],spread:0,threshold:50};
  const med=[median(samples.map(v=>v[0])),median(samples.map(v=>v[1])),median(samples.map(v=>v[2]))],centroids=[med];
  while(centroids.length<4){let far=samples[0],best=-1;for(const s of samples){let d=Infinity;for(const c of centroids)d=Math.min(d,colourDistSq(s[0],s[1],s[2],c));if(d>best){best=d;far=s}}centroids.push([...far])}
  for(let it=0;it<5;it++){const sums=centroids.map(()=>[0,0,0,0]);for(const s of samples){let bi=0,bd=Infinity;for(let k=0;k<centroids.length;k++){const d=colourDistSq(s[0],s[1],s[2],centroids[k]);if(d<bd){bd=d;bi=k}}const z=sums[bi];z[0]+=s[0];z[1]+=s[1];z[2]+=s[2];z[3]++}for(let k=0;k<centroids.length;k++){const z=sums[k];if(z[3])centroids[k]=[z[0]/z[3],z[1]/z[3],z[2]/z[3]]}}
  const borderDist=samples.map(s=>Math.sqrt(Math.min(...centroids.map(c=>colourDistSq(s[0],s[1],s[2],c))))),spread=percentile(borderDist,.72),noise=percentile(borderDist,.90),threshold=clamp(noise+18+spread*.35,28,88);
