  const previousScores=previous?.analysis?.scores||previous?.scores||null;
  if(previousScores){
    const deltas=keys.map(k=>({k,d:(Number(scores[k])||0)-(Number(previousScores[k])||0)})).sort((a,b)=>b.d-a.d);
    developing=deltas.filter(x=>x.d>=1.5).slice(0,2).map(x=>x.k);
    if(!developing.length&&deltas.length)developing=[deltas[0].k];
    priority=keys.map(k=>({k,s:Number(scores[k])||0,d:(Number(scores[k])||0)-(Number(previousScores[k])||0)}))
      .sort((a,b)=>(a.s+physiqueDeltaWeight(a.d))-(b.s+physiqueDeltaWeight(b.d))).slice(0,2).map(x=>x.k);
  }else{
    const ranked=keys.map(k=>({k,s:Number(scores[k])||0})).sort((a,b)=>b.s-a.s);
    developing=ranked.slice(0,2).map(x=>x.k);
    priority=ranked.slice(-2).reverse().map(x=>x.k);
  }
