function renderCheckin(){
  document.getElementById('checkin').innerHTML=`<div class="card glass hero"><div class="eyebrow">Weekly review</div><h2>One honest check-in.</h2><p class="muted">Weight, one progress video and a short note. Hercules compares this video with your previous review and tells you what is developing and what to prioritise next.</p></div><div class="card glass"><label>Weight (kg)</label><input id="ciWeight" class="input" inputmode="decimal" placeholder="${latestWeight().toFixed(1)}"><label>Progress video</label><label class="upload-box" for="ciVideo"><strong id="videoLabel">Choose this week’s video</strong><span class="small">Full body · varied backgrounds supported · multi-pass recovery can track you through clutter · similar distance helps comparison</span></label><input id="ciVideo" class="hidden" type="file" accept="video/*" onchange="handleProgressVideoSelection(this)"><div id="ciAnalysisArea">${physiqueAnalysisStageHTML()}</div><label style="margin-top:14px">Anything worth noting?</label><textarea id="ciNote" placeholder="Training, appetite, recovery, anything unusual…"></textarea><button class="btn primary" style="width:100%;margin-top:12px" onclick="saveCheckin()">Save weekly check-in</button></div>`;
}

function saveCheckin(){
  const w=Number(document.getElementById('ciWeight').value);if(!w){alert('Add this week’s weight first.');return}
  const v=document.getElementById('ciVideo').files[0],note=document.getElementById('ciNote').value.trim(),date=todayISO();
  if(v&&!pendingPhysiqueAnalysis){alert('Analyse the progress video first so Hercules can save the physique review with this check-in.');return}
  progress.weighIns=(progress.weighIns||[]).filter(x=>x.date!==date);
  progress.weighIns.push({date,weightKg:w,source:'weekly-checkin'});
  progress.weeklyCheckins=(progress.weeklyCheckins||[]).filter(x=>x.week!==weekNo());
  progress.weeklyCheckins.push({date,week:weekNo(),weightKg:w,note,video:v?{name:v.name,size:v.size,type:v.type}:null,analysis:pendingPhysiqueAnalysis?structuredClone(pendingPhysiqueAnalysis):null});
  const coachLine=pendingPhysiqueAnalysis?.feedback?.headline||'';write();resetPhysiqueAnalysis();toast('Weekly check-in saved');renderAll();showTab('progress');if(coachLine)setTimeout(()=>GFCoach.reply(coachLine+'. '+(latestPhysiqueAnalysis()?.analysis?.feedback?.summary||'')),350)
}

