  document.getElementById('settingsSheet').innerHTML=`<div class="grabber"></div><div class="eyebrow">Account</div><div class="account-summary-card">${profileAvatarHTML()}<div class="account-summary-copy"><b>${esc(c.name||clientNameValue())}</b><span>${c.heightCm?esc(c.heightCm)+' cm · ':''}${current?round(current,1)+' kg · ':''}${plan.goal?.targetWeightKg?round(plan.goal.targetWeightKg,1)+' kg goal':''}</span></div><button class="profile-edit-link" type="button" onclick="openProfileEditor()">Edit</button></div><button class="btn primary" style="width:100%;margin-top:4px" onclick="openProfileEditor()">Edit account details</button><button class="btn secondary" style="width:100%;margin-top:8px" onclick="closeSettings();openPhysiqueGallery('current')">Open physique library</button><button class="btn secondary" style="width:100%;margin-top:8px" onclick="downloadJSON(progress,'gain-focus-progress-${plan.client.id}-${todayISO()}.json')">Export progress JSON</button><button class="btn secondary" style="width:100%;margin-top:8px" onclick="downloadJSON(plan,'gain-focus-client-${plan.client.id}.json')">Export client plan</button><div style="margin-top:18px;padding-top:16px;border-top:1px solid var(--line)"><div class="eyebrow">Hercules AI</div><p class="muted" style="font-size:12px;line-height:1.45;margin:7px 0 9px">Local smart coaching works without a server. Add a secure model endpoint later for fully open-ended questions.</p><input id="herculesEndpointSetting" class="input" placeholder="https://your-domain.com/api/hercules" value="${esc(herculesEndpoint())}"><button class="btn secondary" style="width:100%;margin-top:8px" onclick="setHerculesEndpoint(document.getElementById('herculesEndpointSetting').value)">Save AI endpoint</button></div><button class="btn secondary" style="width:100%;margin-top:8px" onclick="closeSettings()">Close</button>`;
  document.getElementById('settingsModal').classList.add('open');
