  return {profile:{name:clientNameValue()||'',age:plan?.client?.age||'',sex:plan?.client?.sex||'male',heightCm:plan?.client?.heightCm||'',weightKg:w,sessions:Number(plan?.training?.sessionsPerWeek||4),equipment:'gym',experience:'intermediate',weekdays:[1,2,4,5]},videos:{front:null,side:null,back:null},analysis:null,goal:{targetWeightKg:Number(plan?.goal?.targetWeightKg)||round(w*1.12,1),weeklyGainKg:Number(plan?.goal?.weeklyGainKg)||.25,focus:[...(plan?.goal?.focus||[])]},nutrition:{calories:Number(plan?.nutrition?.calories)||t.calories,proteinG:Number(plan?.nutrition?.proteinG)||t.protein,carbsG:Number(plan?.nutrition?.carbsG)||t.carbs,fatG:Number(plan?.nutrition?.fatG)||t.fat}}
