async function analyseCanonicalVideoFile(file){const r=await analyseVideoSilhouetteRobust(file,null,{thumbnails:false,maxW:210,fractions:[.08,.17,.27,.38,.50,.62,.73,.83,.92]});return {...r.metrics,quality:r.quality,framesAnalysed:r.used,recoveryMode:r.mode}}
async function analyseCanonicalBaseline(){
  const files=Object.values(canonicalOnboarding.videos).filter(Boolean);if(files.length<3){toast('Add front, side and back baseline videos first');return}
  const btn=document.getElementById('canonAnalyseBtn');if(btn){btn.disabled=true;btn.textContent='Analysing…'}
  const metrics=[];for(const f of files){try{metrics.push(await analyseCanonicalVideoFile(f))}catch{}}
  let scores;if(metrics.length>=2){const m={armRatio:meanMetric(metrics,'armRatio'),chestH:meanMetric(metrics,'chestH'),waistH:meanMetric(metrics,'waistH'),legH:meanMetric(metrics,'legH'),taper:meanMetric(metrics,'taper'),shoulderH:meanMetric(metrics,'shoulderH')};scores=scorePhysiqueMetrics(m)}else{scores={arms:55,chest:48,lats:50,shoulders:56,legs:54}}
  const ordered=Object.entries(scores).sort((a,b)=>b[1]-a[1]),developing=ordered.slice(0,2).map(x=>x[0]),priority=ordered.slice(-2).reverse().map(x=>x[0]),maintain=ordered.slice(2,3).map(x=>x[0]);
  canonicalOnboarding.analysis={engine:metrics.length>=2?'local-silhouette-baseline-v1':'baseline-fallback-v1',framesAnalysed:metrics.length,scores:Object.fromEntries(Object.entries(scores).map(([k,v])=>[k,round(v,1)])),developing,maintain,priority,summary:`${regionLabel(developing[0])} currently reads as a relative strength. ${regionLabel(priority[0])} is the clearest candidate for extra emphasis in the first training block.`};
  canonicalOnboarding.goal.focus=[...priority.map(regionLabel),...maintain.map(regionLabel)];canonicalNext()
}
function canonicalGoalSave(){const g=canonicalOnboarding.goal,target=Number(document.getElementById('canGoalWeight')?.value),rate=Number(document.getElementById('canGainRate')?.value),focus=String(document.getElementById('canFocus')?.value||'').split(',').map(x=>x.trim()).filter(Boolean);if(!target||target<canonicalOnboarding.profile.weightKg){toast('Check the goal weight');return}g.targetWeightKg=round(target,1);g.weeklyGainKg=clamp(rate||.25,.05,.75);g.focus=focus.length?focus:g.focus;canonicalNext()}
function canonicalSlug(s){return String(s||'exercise').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function canonicalSessions(){return starterSessions(canonicalOnboarding.profile.sessions).map((s,si)=>({...s,exercises:(s.exercises||[]).map((e,ei)=>({...e,id:e.id||`${canonicalSlug(e.name)}-${si}-${ei}`,incrementKg:Number(e.incrementKg)||(/leg press|deadlift|rdl|squat/i.test(e.name)?5:2.5)}))}))}
function canonicalPlanPreview(){const o=canonicalOnboarding,p=o.profile,g=o.goal,n=o.nutrition,sessions=canonicalSessions();return {schema:'gain-focus-plan/v4',appVersion:APP_VERSION,client:{id:'gf-'+Date.now().toString(36),name:p.name,age:p.age,sex:p.sex,heightCm:p.heightCm,startWeightKg:p.weightKg,equipment:p.equipment,experience:p.experience},goal:{label:'Build muscle and bodyweight',startDate:todayISO(),targetWeightKg:g.targetWeightKg,weeklyGainKg:g.weeklyGainKg,focus:g.focus,summary:'Build controlled lean mass while using repeated visual reviews and training performance to direct emphasis.'},nutrition:{calories:Number(n.calories),proteinG:Number(n.proteinG),carbsG:Number(n.carbsG),fatG:Number(n.fatG),planPurchased:false,adjustmentRule:'Use the 14-day trend. If weight gain is consistently below target, add a small calorie increase; if consistently above target, reduce slightly.'},training:{name:`${p.sessions}-day adaptive hypertrophy`,summary:`${p.sessions} weekly sessions generated around the selected availability and current visual priorities.`,sessionsPerWeek:p.sessions,progressionRule:'Double progression: keep the load until all prescribed sets reach the top of the rep range with clean technique and at least 1 RIR, then increase load and rebuild from the lower end.',sessions},onboarding:{version:'4.0',completedAt:new Date().toISOString(),baselineAnalysis:o.analysis,selectedWeekdays:p.weekdays}}}
