// Keep onboarding in the DOM so Settings can replay it later.
function finishOnboardingToApp(){const ob=document.getElementById('onboarding');if(ob){ob.style.opacity='0';ob.style.transform='scale(1.01)';ob.style.transition='opacity .26s ease,transform .32s var(--spring)';setTimeout(()=>{ob.classList.remove('open');ob.style=''},280)}setTimeout(enterApp,290)}
function replayOnboarding(){closeSettings();const ob=document.getElementById('onboarding');if(!ob)return;document.getElementById('app').classList.remove('open');document.getElementById('nav').classList.add('hidden');ob.classList.add('open');renderCreateUser()}

// ===== Full workout engine: load × reps + RIR, automatic rest, history and next-load suggestion =====
function ensureWorkoutSettings(){ensureProgressExtras();if(!Number(progress.settings.restSeconds))progress.settings.restSeconds=120;if(typeof progress.settings.sound!=='boolean')progress.settings.sound=true}
function workoutExerciseKey(e){return e.id||canonicalSlug(e.name)}
function currentWorkoutRecord(){if(!canonicalWorkout)return null;return (progress.workoutLogs||[]).find(x=>x.id===canonicalWorkout.workoutId)||null}
function previousExercisePerformance(sessionId,e){ensureProgressExtras();const key=workoutExerciseKey(e);const rows=(progress.workoutLogs||[]).filter(w=>w.completed!==false&&w.sessionId===sessionId&&Array.isArray(w.setEntries)&&w.setEntries.some(s=>s.exerciseKey===key)).sort((a,b)=>String(b.completedAt||b.date).localeCompare(String(a.completedAt||a.date)));if(!rows.length)return[];return rows[0].setEntries.filter(s=>s.exerciseKey===key)}
function suggestedLoadFor(sessionId,e){const sets=previousExercisePerformance(sessionId,e);if(!sets.length)return {load:'',message:'No previous load — choose a controlled starting weight.'};const loads=sets.map(s=>Number(s.weightKg)||0),base=Math.max(...loads),allTop=sets.length>=Number(e.sets||1)&&sets.slice(-Number(e.sets||1)).every(s=>Number(s.reps)>=Number(e.repMax||999)&&Number(s.rir)>=1),inc=Number(e.incrementKg)||(/leg press|deadlift|rdl|squat/i.test(e.name)?5:2.5),next=allTop?round(base+inc,2):base;return {load:next,message:allTop?`Last time all working sets reached ${e.repMax} reps with ≥1 RIR. Suggested +${inc} kg.`:`Repeat ${base} kg and try to add clean reps before increasing load.`}}
function workoutBeep(){if(!progress?.settings?.sound)return;try{const a=new(window.AudioContext||window.webkitAudioContext)(),o=a.createOscillator(),g=a.createGain();o.frequency.value=880;g.gain.value=.04;o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.15)}catch{}}
function formatRest(s){return `${Math.floor(Math.max(0,s)/60)}:${String(Math.max(0,s)%60).padStart(2,'0')}`}
function runCanonicalRestInterval(){clearInterval(canonicalRestHandle);canonicalRestPaused=false;canonicalRestHandle=setInterval(()=>{if(canonicalRestPaused)return;canonicalRestRemaining--;const el=document.getElementById('canonicalRestClock');if(el)el.textContent=formatRest(canonicalRestRemaining);if(canonicalRestRemaining<=0){clearInterval(canonicalRestHandle);canonicalRestHandle=null;canonicalRestRemaining=0;workoutBeep()}},1000)}
function startCanonicalRest(seconds=null){ensureWorkoutSettings();canonicalRestRemaining=Math.max(1,Number(seconds)||Number(progress.settings.restSeconds)||120);runCanonicalRestInterval();const el=document.getElementById('canonicalRestClock');if(el)el.textContent=formatRest(canonicalRestRemaining)}
function toggleCanonicalRest(){if(!canonicalRestRemaining){startCanonicalRest();return}canonicalRestPaused=!canonicalRestPaused;const b=document.getElementById('restPauseBtn');if(b)b.textContent=canonicalRestPaused?'Resume':'Pause'}
function addCanonicalRest(seconds=30){canonicalRestRemaining=Math.max(0,canonicalRestRemaining)+Number(seconds||0);if(!canonicalRestHandle&&canonicalRestRemaining>0)runCanonicalRestInterval();const el=document.getElementById('canonicalRestClock');if(el)el.textContent=formatRest(canonicalRestRemaining)}
function skipCanonicalRest(){clearInterval(canonicalRestHandle);canonicalRestHandle=null;canonicalRestRemaining=0;canonicalRestPaused=false;const el=document.getElementById('canonicalRestClock');if(el)el.textContent='Ready';const b=document.getElementById('restPauseBtn');if(b)b.textContent='Start'}
function setWorkoutRIR(v){if(!canonicalWorkout)return;canonicalWorkout.rir=v;document.querySelectorAll('.rir-row button').forEach(b=>b.classList.toggle('on',Number(b.dataset.rir)===v))}
function startWorkout(id){ensureWorkoutSettings();const s=plan.training.sessions.find(x=>x.id===id);if(!s)return;let w=(progress.workoutLogs||[]).find(x=>x.completed===false&&x.sessionId===id&&x.date===todayISO());if(!w){w={id:'workout-'+canonicalUid(),date:todayISO(),startedAt:new Date().toISOString(),completed:false,sessionId:s.id,sessionName:s.name,setEntries:[],exercises:[]};progress.workoutLogs.push(w);write()}canonicalWorkout={workoutId:w.id,sessionId:id,exerciseIndex:0,rir:2};renderCanonicalWorkout()}
function renderCanonicalWorkout(){
  const w=currentWorkoutRecord();if(!w||!canonicalWorkout)return;
  const s=plan.training.sessions.find(x=>x.id===w.sessionId),i=clamp(canonicalWorkout.exerciseIndex,0,s.exercises.length-1),e=s.exercises[i],key=workoutExerciseKey(e),today=w.setEntries.filter(x=>x.exerciseKey===key),suggest=suggestedLoadFor(s.id,e),targetSets=Number(e.sets)||0;
  canonicalWorkout.exerciseIndex=i;
  const nextSetNo=Math.min(today.length+1,targetSets||today.length+1), remaining=Math.max((targetSets||0)-today.length,0);
  const sessionSheet=document.getElementById('sessionSheet');
  sessionSheet.classList.add('workout-sheet');
  sessionSheet.innerHTML=`<div class="grabber"></div><div class="workout-shell"><div class="eyebrow">${esc(s.name)} · Exercise ${i+1} of ${s.exercises.length}</div><div class="workout-engine-head"><div class="exercise-guide-thumb">${exerciseVisual(e,false)}</div><div class="grow"><h2>${esc(e.name)}</h2><div class="workout-subhead"><p class="muted" style="margin:0">${targetSets} × ${e.repMin}–${e.repMax} · ${esc(e.focus||'')}</p><span class="set-count">Set ${nextSetNo}${targetSets?` / ${targetSets}`:''}</span></div></div></div><div class="workout-progress-line"><span class="small">Log each working set below. The rest timer starts automatically after you save a set.</span><span class="small">${remaining>0?`${remaining} set${remaining===1?'':'s'} remaining`:`All target sets logged`}</span></div><div class="workout-status-grid"><div class="next-load"><span>Next-load guidance</span><b>${esc(suggest.message)}</b></div><div class="rest-panel"><div class="rest-clock"><span>Rest timer</span><b id="canonicalRestClock">${canonicalRestRemaining?formatRest(canonicalRestRemaining):'Ready'}</b></div><div class="rest-actions"><button id="restPauseBtn" class="primary-rest" type="button" onclick="toggleCanonicalRest()">${canonicalRestRemaining?(canonicalRestPaused?'Resume':'Pause'):'Start'}</button><button type="button" onclick="addCanonicalRest(30)">+30 sec</button><button type="button" onclick="skipCanonicalRest()">Skip</button></div></div></div><div class="workout-inputs"><div class="workout-input-card"><label>Weight / load kg</label><input id="canonicalSetWeight" class="input" inputmode="decimal" value="${suggest.load}" placeholder="kg"></div><div class="workout-input-card"><label>Reps</label><input id="canonicalSetReps" class="input" inputmode="numeric" placeholder="${e.repMin}"></div></div><div class="workout-rir"><label>Reps in reserve</label><div class="rir-row">${[0,1,2,3].map(r=>`<button type="button" data-rir="${r}" class="${canonicalWorkout.rir===r?'on':''}" onclick="setWorkoutRIR(${r})">${r} RIR</button>`).join('')}</div></div><div class="workout-primary-row"><button class="btn primary" onclick="saveCanonicalSet()">Log set & start rest</button></div><div class="set-history-title"><b>Logged sets</b><span>${today.length} logged</span></div><div class="set-history">${today.length?today.map((x,j)=>`<div class="set-history-row"><div class="set-main"><span>Set ${j+1} · ${x.rir} RIR</span><b>${x.weightKg?x.weightKg+' kg':'BW'} × ${x.reps}</b></div><div class="set-actions"><button class="set-edit" type="button" onclick="editActiveWorkoutSet('${x.id}')">Edit</button></div></div>`).join(''):`<div class="small" style="text-align:center;padding:12px">No working sets logged yet.</div>`}</div><div class="workout-secondary-links"><div class="workout-nav"><button class="btn secondary" onclick="canonicalWorkout.exerciseIndex=Math.max(0,canonicalWorkout.exerciseIndex-1);renderCanonicalWorkout()">← Previous</button><button class="btn secondary" onclick="canonicalWorkout.exerciseIndex=Math.min(${s.exercises.length-1},canonicalWorkout.exerciseIndex+1);renderCanonicalWorkout()">Next →</button></div><a class="workout-guide-btn" href="javascript:void(0)" onclick="openExerciseGuide('${s.id}',${i})">Open form guide <span>/ video ↗</span></a></div><div class="workout-dock"><button class="btn primary" onclick="finishCanonicalWorkout()">Finish workout</button><button class="btn secondary" onclick="closeSession()">End later</button></div><div class="workout-spacer"></div></div>`;
  document.getElementById('sessionModal').classList.add('open')
}
function saveCanonicalSet(){
  const w=currentWorkoutRecord();if(!w||!canonicalWorkout)return;const s=plan.training.sessions.find(x=>x.id===w.sessionId),e=s.exercises[canonicalWorkout.exerciseIndex],weight=Math.max(0,Number(document.getElementById('canonicalSetWeight')?.value)||0),reps=Math.max(0,Math.round(Number(document.getElementById('canonicalSetReps')?.value)||0));
  if(!reps){toast('Add reps first');return}
  w.setEntries.push({id:canonicalUid(),ts:Date.now(),exerciseKey:workoutExerciseKey(e),exerciseName:e.name,focus:e.focus||'',weightKg:weight,reps,rir:Number(canonicalWorkout.rir)});write();startCanonicalRest();renderCanonicalWorkout()
}
function editActiveWorkoutSet(setId){
  const w=currentWorkoutRecord();if(!w)return;const row=(w.setEntries||[]).find(x=>x.id===setId);if(!row)return;
  const weight=prompt('Weight / load kg',row.weightKg||0);if(weight===null)return;const reps=prompt('Reps',row.reps||0);if(reps===null)return;const rir=prompt('RIR (0–5)',row.rir??2);if(rir===null)return;
  row.weightKg=Math.max(0,Number(weight)||0);row.reps=Math.max(1,Math.round(Number(reps)||1));row.rir=clamp(Math.round(Number(rir)||0),0,5);write();renderCanonicalWorkout();toast('Set updated')
}
function finishCanonicalWorkout(){const w=currentWorkoutRecord();if(!w)return;const s=plan.training.sessions.find(x=>x.id===w.sessionId);if(!w.setEntries.length){toast('Log at least one working set');return}w.exercises=(s.exercises||[]).map(e=>({id:workoutExerciseKey(e),name:e.name,focus:e.focus||'',sets:w.setEntries.filter(x=>x.exerciseKey===workoutExerciseKey(e)).length})).filter(x=>x.sets>0);w.completed=true;w.completedAt=new Date().toISOString();write();clearInterval(canonicalRestHandle);canonicalRestHandle=null;canonicalRestRemaining=0;canonicalRestPaused=false;canonicalWorkout=null;closeSession();toast('Workout saved — progression and heat map updated');renderAll();showTab('progress')}

// Save actual weekly video file locally with the analysis record.
async function saveCheckin(){const w=Number(document.getElementById('ciWeight')?.value);if(!w){alert('Add this week’s weight first.');return}const input=document.getElementById('ciVideo'),v=input?.files?.[0]||null,note=document.getElementById('ciNote')?.value.trim()||'',date=todayISO();if(v&&!pendingPhysiqueAnalysis){alert('Analyse the progress video first so Hercules can save the physique review with this check-in.');return}progress.weighIns=(progress.weighIns||[]).filter(x=>x.date!==date);progress.weighIns.push({date,weightKg:w,source:'weekly-checkin'});progress.weeklyCheckins=(progress.weeklyCheckins||[]).filter(x=>x.historic||x.week!==weekNo());let media=null;if(v){try{const key=`checkin-week-${weekNo()}-${canonicalUid()}`;await saveMediaBlob(key,v);media={key,name:v.name,size:v.size,type:v.type}}catch{media={name:v.name,size:v.size,type:v.type}}}progress.weeklyCheckins.push({date,week:weekNo(),weightKg:w,note,video:media,analysis:pendingPhysiqueAnalysis?structuredClone(pendingPhysiqueAnalysis):null});const coachLine=pendingPhysiqueAnalysis?.feedback?.headline||'';write();resetPhysiqueAnalysis();toast('Weekly check-in saved');renderAll();showTab('progress');if(coachLine)setTimeout(()=>GFCoach.reply(coachLine+'. '+(latestPhysiqueAnalysis()?.analysis?.feedback?.summary||'')),350)}

// Nutrition edit: photo entries only edit consumed amount; manual entries edit their logged values.
function editNutritionEntry(id){ensureProgressExtras();const x=progress.nutritionLogs.find(v=>v.id===id);if(!x)return;if(x.source==='photo-ocr'&&x.labelNutrition){const amount=Number(prompt(`How much did you consume? (${x.quantityUnit||'servings'})`,x.quantity||1));if(!amount||amount<=0)return;const calc=nutritionAmountCalculation(x.labelNutrition,amount,x.quantityUnit||nutritionQuantityModes(x.labelNutrition)[0]?.value);if(!calc)return;x.quantity=calc.amount;x.quantityUnit=calc.unit;x.calories=calc.calories;x.protein=calc.protein;x.carbs=calc.carbs;x.fat=calc.fat}else{const name=prompt('Food name',x.name||'Food');if(name===null)return;x.name=name.trim()||x.name;for(const [k,label] of [['calories','Calories'],['protein','Protein g'],['carbs','Carbs g'],['fat','Fat g']]){const v=prompt(label,x[k]??0);if(v===null)return;x[k]=Math.max(0,Number(v)||0)}}write();renderNutrition();toast('Food entry updated')}


// Workout history: view, edit, add/remove sets and recalculate heat-map set totals.
function workoutEntryList(w){return Array.isArray(w?.setEntries)?w.setEntries:[]}
function workoutTotalSets(w){const detailed=workoutEntryList(w).length;if(detailed)return detailed;return (w?.exercises||[]).reduce((n,e)=>n+(Number(e.sets)||0),0)}
function workoutVolume(w){return workoutEntryList(w).reduce((n,s)=>n+(Number(s.weightKg)||0)*(Number(s.reps)||0),0)}
function workoutDisplayDate(w){try{return new Date((w?.date||todayISO())+'T12:00:00').toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}catch{return w?.date||''}}
function sortedWorkoutLogs(){ensureProgressExtras();return [...(progress.workoutLogs||[])].sort((a,b)=>String(b.completedAt||b.startedAt||b.date).localeCompare(String(a.completedAt||a.startedAt||a.date)))}
function workoutHistoryHTML(limit=0){const rows=sortedWorkoutLogs(),list=limit?rows.slice(0,limit):rows;if(!list.length)return `<div class="workout-history-empty">No workouts logged yet. Start a session and your weights, reps and sets will appear here.</div>`;return `<div class="workout-history">${list.map(w=>{const sets=workoutTotalSets(w),vol=workoutVolume(w);return `<button class="workout-history-card ${w.completed===false?'in-progress':''}" onclick="openWorkoutEditor('${w.id}')"><div><span class="wh-title">${esc(w.sessionName||'Workout')}</span><span class="wh-meta">${workoutDisplayDate(w)}${w.completed===false?' · In progress':''}</span><div class="wh-stats"><span class="wh-stat">${sets} set${sets===1?'':'s'}</span>${vol?`<span class="wh-stat">${Math.round(vol).toLocaleString()} kg volume</span>`:''}</div></div><span class="wh-edit">View / edit ›</span></button>`}).join('')}</div>`}
function workoutHistoryMiniHTML(){const rows=sortedWorkoutLogs();if(!rows.length)return'';return `<div class="section"><h3>Recent workouts</h3><span class="small">Tap to view or edit</span></div>${workoutHistoryHTML(3)}`}
function hydrateLegacyWorkout(w){if(Array.isArray(w.setEntries)&&w.setEntries.length)return;w.setEntries=[];const s=plan.training.sessions.find(x=>x.id===w.sessionId);(w.exercises||[]).forEach(ex=>{const pe=s?.exercises?.find(e=>workoutExerciseKey(e)===(ex.id||ex.exerciseKey)||e.name===ex.name),count=Math.max(0,Number(ex.sets)||0);for(let i=0;i<count;i++)w.setEntries.push({id:canonicalUid(),ts:Date.now(),exerciseKey:ex.id||ex.exerciseKey||workoutExerciseKey(pe||ex),exerciseName:ex.name||pe?.name||'Exercise',focus:ex.focus||pe?.focus||'',weightKg:0,reps:0,rir:2})})}
function recalcWorkoutExercises(w){const s=plan.training.sessions.find(x=>x.id===w.sessionId),groups={};(w.setEntries||[]).forEach(x=>{const k=x.exerciseKey||canonicalSlug(x.exerciseName);groups[k]||(groups[k]={id:k,name:x.exerciseName||s?.exercises?.find(e=>workoutExerciseKey(e)===k)?.name||'Exercise',focus:x.focus||s?.exercises?.find(e=>workoutExerciseKey(e)===k)?.focus||'',sets:0});groups[k].sets++});w.exercises=Object.values(groups)}
function workoutEditorExerciseKeys(w){const s=plan.training.sessions.find(x=>x.id===w.sessionId),keys=[];(s?.exercises||[]).forEach(e=>{const k=workoutExerciseKey(e);if((w.setEntries||[]).some(x=>x.exerciseKey===k))keys.push(k)});(w.setEntries||[]).forEach(x=>{if(!keys.includes(x.exerciseKey))keys.push(x.exerciseKey)});return keys}
function openWorkoutEditor(id){ensureProgressExtras();const w=(progress.workoutLogs||[]).find(x=>x.id===id);if(!w)return;hydrateLegacyWorkout(w);editingWorkoutId=id;const s=plan.training.sessions.find(x=>x.id===w.sessionId),keys=workoutEditorExerciseKeys(w);document.getElementById('sessionSheet').classList.remove('workout-sheet');document.getElementById('sessionSheet').innerHTML=`<div class="grabber"></div><div class="workout-editor-head"><div><div class="eyebrow">Workout history</div><h2 style="font-size:29px;margin:5px 0 2px">${esc(w.sessionName||s?.name||'Workout')}</h2><p class="muted" style="margin:0">Edit any set below. Saving recalculates the muscle heat map and future load suggestions.</p></div><input id="workoutEditDate" class="input workout-editor-date" type="date" value="${esc(w.date||todayISO())}"></div><div class="workout-editor-exercises">${keys.map(k=>workoutEditorExerciseHTML(w,k,s)).join('')}</div><div class="workout-editor-actions"><button class="btn secondary" onclick="closeSession()">Close</button><button class="btn primary" onclick="saveWorkoutEdits('${w.id}')">Save changes</button></div>${w.completed===false?`<button class="btn secondary" style="width:100%;margin-top:8px" onclick="resumeWorkout('${w.id}')">Resume workout</button>`:''}<button class="btn secondary settings-danger" style="width:100%;margin-top:8px" onclick="deleteWorkoutLog('${w.id}')">Delete workout</button>`;document.getElementById('sessionModal').classList.add('open')}
function workoutEditorExerciseHTML(w,key,s){const pe=s?.exercises?.find(e=>workoutExerciseKey(e)===key),sets=(w.setEntries||[]).filter(x=>x.exerciseKey===key),name=pe?.name||sets[0]?.exerciseName||'Exercise';return `<div class="workout-editor-exercise"><div class="workout-editor-exercise-head"><b>${esc(name)}</b><button type="button" onclick="addWorkoutHistorySet('${w.id}','${key}')">+ Add set</button></div><div class="workout-edit-labels"><span>#</span><span>kg</span><span>reps</span><span>RIR</span><span></span></div>${sets.length?sets.map((x,i)=>`<div class="workout-edit-set" data-set-id="${x.id}"><span class="set-index">${i+1}</span><input class="edit-weight" inputmode="decimal" value="${Number(x.weightKg)||''}" placeholder="BW"><input class="edit-reps" inputmode="numeric" value="${Number(x.reps)||''}" placeholder="reps"><select class="edit-rir">${[0,1,2,3,4,5].map(r=>`<option value="${r}" ${Number(x.rir)===r?'selected':''}>${r}</option>`).join('')}</select><button class="delete-set" type="button" onclick="deleteWorkoutHistorySet('${w.id}','${x.id}')">×</button></div>`).join(''):`<div class="small" style="padding:7px 0">No sets logged.</div>`}</div>`}
function saveWorkoutEdits(id){const w=(progress.workoutLogs||[]).find(x=>x.id===id);if(!w)return;document.querySelectorAll('.workout-edit-set').forEach(row=>{const x=(w.setEntries||[]).find(v=>v.id===row.dataset.setId);if(!x)return;x.weightKg=Math.max(0,Number(row.querySelector('.edit-weight')?.value)||0);x.reps=Math.max(0,Math.round(Number(row.querySelector('.edit-reps')?.value)||0));x.rir=clamp(Math.round(Number(row.querySelector('.edit-rir')?.value)||0),0,5)});const date=document.getElementById('workoutEditDate')?.value;if(/^\d{4}-\d{2}-\d{2}$/.test(date||'')){w.date=date;if(w.startedAt)w.startedAt=date+String(w.startedAt).slice(10);if(w.completedAt)w.completedAt=date+String(w.completedAt).slice(10)}recalcWorkoutExercises(w);write();renderAll();openWorkoutEditor(id);toast('Workout updated')}
function addWorkoutHistorySet(id,key){const w=(progress.workoutLogs||[]).find(x=>x.id===id);if(!w)return;const s=plan.training.sessions.find(x=>x.id===w.sessionId),e=s?.exercises?.find(x=>workoutExerciseKey(x)===key),last=[...(w.setEntries||[])].reverse().find(x=>x.exerciseKey===key);w.setEntries.push({id:canonicalUid(),ts:Date.now(),exerciseKey:key,exerciseName:e?.name||last?.exerciseName||'Exercise',focus:e?.focus||last?.focus||'',weightKg:Number(last?.weightKg)||0,reps:Number(last?.reps)||0,rir:Number(last?.rir??2)});recalcWorkoutExercises(w);write();openWorkoutEditor(id)}
function deleteWorkoutHistorySet(id,setId){const w=(progress.workoutLogs||[]).find(x=>x.id===id);if(!w)return;w.setEntries=(w.setEntries||[]).filter(x=>x.id!==setId);recalcWorkoutExercises(w);write();openWorkoutEditor(id)}
function deleteWorkoutLog(id){if(!confirm('Delete this logged workout? This also removes its contribution to the muscle heat map.'))return;progress.workoutLogs=(progress.workoutLogs||[]).filter(x=>x.id!==id);write();editingWorkoutId=null;closeSession();renderAll();toast('Workout deleted')}
function resumeWorkout(id){const w=(progress.workoutLogs||[]).find(x=>x.id===id);if(!w)return;canonicalWorkout={workoutId:w.id,sessionId:w.sessionId,exerciseIndex:0,rir:2};editingWorkoutId=null;renderCanonicalWorkout()}

// Settings: replay onboarding, replace plan, restore progress, rest timer, sound, reset.
function saveCanonicalSettings(){ensureWorkoutSettings();const r=Number(document.getElementById('restSecondsSetting')?.value);if(r>=30&&r<=600)progress.settings.restSeconds=Math.round(r);progress.settings.sound=!!document.getElementById('restSoundSetting')?.checked;write();toast('Workout settings saved')}
function openSettings(){ensureWorkoutSettings();document.getElementById('settingsSheet').innerHTML=`<div class="grabber"></div><div class="eyebrow">Account</div><div class="account-summary-card">${profileAvatarHTML()}<div class="account-summary-copy"><b>${esc(plan.client.name)}</b><span>${plan.client.heightCm?esc(plan.client.heightCm)+' cm · ':''}${round(latestWeight(),1)} kg · ${plan.goal.targetWeightKg} kg goal</span></div><button class="profile-edit-link" type="button" onclick="openProfileEditor()">Edit</button></div><button class="btn primary" style="width:100%;margin-top:4px" onclick="openProfileEditor()">Edit account details</button><button class="btn primary" style="width:100%;margin-top:8px" onclick="closeSettings();openPhysiqueGallery('current')">Open physique library</button><div class="settings-group"><div class="eyebrow">Workout</div><div class="settings-row"><span class="small">Rest timer seconds</span><input id="restSecondsSetting" class="input" type="number" min="30" max="600" value="${progress.settings.restSeconds||120}"></div><div class="settings-row"><span class="small">Timer sound</span><input id="restSoundSetting" type="checkbox" ${progress.settings.sound!==false?'checked':''}></div><button class="btn secondary" style="width:100%;margin-top:8px" onclick="saveCanonicalSettings()">Save workout settings</button></div><div class="settings-group"><div class="eyebrow">Client data</div><button class="btn secondary" style="width:100%;margin-top:8px" onclick="replayOnboarding()">Replay / rebuild onboarding</button><button class="btn secondary" style="width:100%;margin-top:8px" onclick="document.getElementById('settingsPlanFile').click()">Replace client plan JSON</button><button class="btn secondary" style="width:100%;margin-top:8px" onclick="document.getElementById('settingsProgressFile').click()">Restore progress JSON</button><button class="btn secondary" style="width:100%;margin-top:8px" onclick="downloadJSON(progress,'gain-focus-progress-${plan.client.id}-${todayISO()}.json')">Export progress JSON</button><button class="btn secondary" style="width:100%;margin-top:8px" onclick="downloadJSON(plan,'gain-focus-client-${plan.client.id}.json')">Export client plan</button></div><div class="settings-group"><div class="eyebrow">Hercules AI</div><p class="muted" style="font-size:12px;line-height:1.45;margin:7px 0 9px">Local coaching uses training, macros, weight trend, check-ins and physique feedback. Add a secure model endpoint for fully open-ended questions.</p><input id="herculesEndpointSetting" class="input" placeholder="https://your-domain.com/api/hercules" value="${esc(herculesEndpoint())}"><button class="btn secondary" style="width:100%;margin-top:8px" onclick="setHerculesEndpoint(document.getElementById('herculesEndpointSetting').value)">Save AI endpoint</button><button class="btn secondary" style="width:100%;margin-top:8px" onclick="localStorage.removeItem(HERCULES_HISTORY_KEY);toast('Hercules conversation cleared')">Clear Hercules history</button></div><div class="settings-group"><button class="btn secondary settings-danger" style="width:100%" onclick="resetGainFocusLocal()">Reset local client & app</button></div><button class="btn secondary" style="width:100%;margin-top:8px" onclick="closeSettings()">Close</button>`;document.getElementById('settingsModal').classList.add('open')}
async function resetGainFocusLocal(){if(!confirm('Reset the local Gain Focus client, progress, saved media and Hercules history?'))return;localStorage.removeItem(PLAN_KEY);localStorage.removeItem(PROGRESS_KEY);localStorage.removeItem(CLIENT_NAME_KEY);localStorage.removeItem(HERCULES_HISTORY_KEY);await clearMediaDB();location.reload()}
function importSettingsPlan(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!validPlan(x))throw new Error();plan=x;localStorage.setItem(CLIENT_NAME_KEY,x.client.name||'');if(!progress||progress.clientId!==x.client.id)progress=newProgress();write();closeSettings();renderAll();toast('Client plan replaced')}catch{alert('That JSON is not a valid Gain Focus client plan.')}};r.readAsText(file)}
