function ensureWeeklyReviewIds(){
  if(!progress)return;let changed=false;
  progress.weeklyCheckins||(progress.weeklyCheckins=[]);
  progress.weeklyCheckins.forEach((c,i)=>{if(!c.id){c.id=`review-${c.week||i+1}-${String(c.date||todayISO()).replace(/-/g,'')}-${i}`;changed=true}});
  if(changed)write();
}
function sortedWeeklyReviews(){ensureWeeklyReviewIds();return [...(progress.weeklyCheckins||[])].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))}
function reviewDateLabel(c){try{return new Date((c?.date||todayISO())+'T12:00:00').toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}catch{return c?.date||''}}
function weekForReviewDate(date){const start=plan?.goal?.startDate||date;return Math.max(1,Math.floor(Math.max(0,daysBetween(start,date))/7)+1)}
function weeklyReviewHistoryHTML(limit=0){
  const rows=sortedWeeklyReviews(),list=limit?rows.slice(0,limit):rows;
  if(!list.length)return `<div class="card glass muted">Your first weekly review will appear here.</div>`;
  return `<div class="weekly-review-history">${list.map(c=>`<button type="button" class="weekly-review-card" onclick="openWeeklyReviewEditor('${c.id}')"><div class="wr-main"><div class="wr-top"><span class="badge ${c.historic?'historic':''}">${c.historic?'Historic':'Week '+c.week}</span>${c.analysis?'<span class="badge good">Physique reviewed</span>':''}</div><span class="wr-weight">${Number(c.weightKg||0).toFixed(1)} kg</span><span class="wr-meta">${reviewDateLabel(c)} · ${c.video?esc(c.video.name||'Progress video'):'No video'}</span>${c.note?`<span class="wr-note">${esc(c.note)}</span>`:''}</div><span class="wr-open">View / edit ›</span></button>`).join('')}</div>`
}
function findWeeklyReview(id){ensureWeeklyReviewIds();return (progress.weeklyCheckins||[]).find(x=>x.id===id)||null}
function getMediaBlob(key){return new Promise(async(resolve,reject)=>{if(!key){resolve(null);return}try{const db=await mediaDB();const tx=db.transaction('media','readonly'),r=tx.objectStore('media').get(key);r.onsuccess=()=>{const v=r.result||null;db.close();resolve(v)};r.onerror=()=>{db.close();reject(r.error)}}catch(e){reject(e)}})}
function weeklyReviewPreviousAnalysis(review){return [...(progress.weeklyCheckins||[])].filter(x=>x.id!==review.id&&x.analysis&&x.analysis.scores&&String(x.date||'')<String(review.date||'')).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))[0]||null}

