async function viewWeeklyReviewVideo(id){const c=findWeeklyReview(id);if(!c?.video?.key){toast('The original video file is not available on this device');return}try{const blob=await getMediaBlob(c.video.key);if(!blob){toast('The saved video file could not be found');return}if(weeklyReviewPlayerURL)URL.revokeObjectURL(weeklyReviewPlayerURL);weeklyReviewPlayerURL=URL.createObjectURL(blob);document.getElementById('sessionSheet').innerHTML=`<div class="grabber"></div><button class="btn ghost" style="width:auto;padding:6px 2px;margin:0 0 3px" onclick="openWeeklyReviewEditor('${c.id}')">‹ Back to review</button><div class="eyebrow">Week ${c.week} · progress video</div><h2 style="font-size:27px;margin:6px 0 0">${esc(c.video.name||'Progress video')}</h2><video class="review-video-player" src="${weeklyReviewPlayerURL}" controls playsinline></video><button class="btn secondary" style="width:100%;margin-top:10px" onclick="openWeeklyReviewEditor('${c.id}')">Back to review</button>`}catch{toast('Could not open the saved video')}}
async function saveWeeklyReviewEdits(id){const c=findWeeklyReview(id);if(!c)return;const date=document.getElementById('reviewEditDate')?.value,weight=Number(document.getElementById('reviewEditWeight')?.value),note=String(document.getElementById('reviewEditNote')?.value||'').trim();if(!/^\d{4}-\d{2}-\d{2}$/.test(date||'')||!weight||weight<30||weight>300||date>todayISO()){toast('Check the date and weight');return}const nextWeek=weekForReviewDate(date);const duplicate=(progress.weeklyCheckins||[]).find(x=>x.id!==id&&(c.historic?String(x.date||'')===date:(!x.historic&&Number(x.week)===nextWeek)));if(duplicate&&!confirm(c.historic?'A check-in already exists on that date. Keep both?':`Week ${nextWeek} already has a review. Keep both reviews in that week?`))return;const oldDate=c.date,oldKey=c.video?.key||null,newFile=document.getElementById('reviewVideoFile')?.files?.[0]||null;if(newFile){let media={name:newFile.name,size:newFile.size,type:newFile.type};try{const key=`checkin-${c.historic?'historic':'week'}-${nextWeek}-${canonicalUid()}`;await saveMediaBlob(key,newFile);media={...media,key};if(oldKey)await deleteMediaBlob(oldKey)}catch{}c.video=media;c.analysis=weeklyReviewReplacementAnalysis?structuredClone(weeklyReviewReplacementAnalysis):null}else if(weeklyReviewRemoveVideo){if(oldKey)await deleteMediaBlob(oldKey);c.video=null;c.analysis=null}c.date=date;c.week=nextWeek;c.weightKg=round(weight,1);c.note=note;const source=c.historic?'historic-checkin':'weekly-checkin';progress.weighIns=(progress.weighIns||[]).filter(x=>!(x.source===source&&x.date===oldDate));progress.weighIns=progress.weighIns.filter(x=>x.date!==date||x.source!==source);progress.weighIns.push({date,weightKg:c.weightKg,source});write();editingWeeklyReviewId=null;weeklyReviewReplacementAnalysis=null;weeklyReviewRemoveVideo=false;closeSession();renderAll();showTab('progress');toast(c.historic?'Historic check-in updated':'Weekly review updated')}
async function deleteWeeklyReview(id){const c=findWeeklyReview(id);if(!c||!confirm(`Delete this ${c.historic?'historic check-in':'Week '+c.week+' review'}? This removes its saved weight and locally stored progress video.`))return;if(c.video?.key)await deleteMediaBlob(c.video.key);progress.weeklyCheckins=(progress.weeklyCheckins||[]).filter(x=>x.id!==id);const source=c.historic?'historic-checkin':'weekly-checkin';progress.weighIns=(progress.weighIns||[]).filter(x=>!(x.source===source&&x.date===c.date));write();editingWeeklyReviewId=null;closeSession();renderAll();showTab('progress');toast(c.historic?'Historic check-in deleted':'Weekly review deleted')}


