async function analyseHistoricCheckinVideo(){const file=document.getElementById('historicVideoFile')?.files?.[0],date=document.getElementById('historicDate')?.value||todayISO(),status=document.getElementById('historicAnalysisStatus'),btn=document.getElementById('historicAnalyseBtn');if(!file){toast('Choose a historic video first');return}if(btn)btn.disabled=true;if(status){status.className='historic-analysis-status working';status.textContent='Multi-pass analysis · preparing historic video…'}try{const result=await analyseVideoSilhouetteRobust(file,info=>{if(status)status.textContent=info.message||(info.stage==='sample'?`Scanning frame ${info.index+1} of ${info.total}`:'Analysing…')},{thumbnails:false,maxW:220});const m=result.metrics,scores=scorePhysiqueMetrics(m),prev=historicPreviousAnalysis(date),feedback=(typeof buildPhysiqueFeedback==='function'?buildPhysiqueFeedback(scores,prev):{headline:'Historic physique review ready',summary:'The historic video was analysed successfully.',developing:[],priority:[],maintain:[],training:'Use this as a visual baseline for later comparisons.'});if(result.mode!=='robust')feedback.summary=`${feedback.summary} ${result.mode==='provisional'?'This historic review is provisional because only one dependable body frame could be recovered.':'This clip needed temporal recovery, so small differences should be treated cautiously.'}`;historicCheckinAnalysis={engine:'adaptive-silhouette-v3',createdAt:new Date().toISOString(),historic:true,framesAnalysed:result.used,framesSampled:result.total,rejectedFrames:result.rejected,quality:result.quality,recoveryMode:result.mode,segmentationMethods:result.methods,metrics:Object.fromEntries(Object.entries(m).map(([k,v])=>[k,round(v,4)])),scores:Object.fromEntries(Object.entries(scores).map(([k,v])=>[k,round(v,1)])),previousWeek:prev?.week||null,feedback};const preview=document.getElementById('historicAnalysisPreview');if(preview)preview.innerHTML=physiqueAnalysisCard(historicCheckinAnalysis,false);if(status){status.className='historic-analysis-status done';status.textContent=result.mode==='robust'?`Historic analysis ready · ${result.used}/${result.total} stable frames used.`:`Historic analysis recovered · ${result.used}/${result.total} usable frames.`}}catch(e){console.error(e);historicCheckinAnalysis=null;if(status){status.className='historic-analysis-status error';status.textContent=e?.message||'Could not analyse this historic video.'}}finally{if(btn)btn.disabled=false}}
