// v4.0.16 chart layout refinement: keep marked axes and legends clear on mobile.
buildLineChartSVG=function({series,width=640,height=230,yLabel='kg',emptyText='No data yet',legend=[],yTickFormatter=v=>String(v),xTicks=null}){
  const all=(series||[]).flatMap(s=>(s.points||[]).map(p=>({...p,_label:s.label,_color:s.color,_dash:s.dash||''})));
  if(!all.length)return `<div class="muted" style="padding:82px 20px;text-align:center">${emptyText}</div>`;
  const margin={top:20,right:14,bottom:56,left:50},plotW=width-margin.left-margin.right,plotH=height-margin.top-margin.bottom;
  const dates=[...new Set(all.map(p=>p.date))].sort((a,b)=>a.localeCompare(b));
  const t0=new Date(dates[0]+'T12:00:00').getTime(),t1=new Date(dates.at(-1)+'T12:00:00').getTime(),tSpan=Math.max(86400000,t1-t0);
  const vals=all.map(p=>Number(p.value)).filter(Number.isFinite);let min=Math.min(...vals),max=Math.max(...vals);if(min===max){min-=1;max+=1}const pad=Math.max((max-min)*.12,.6);min-=pad;max+=pad;const span=Math.max(1,max-min);
  const x=d=>margin.left+((new Date(d+'T12:00:00').getTime()-t0)/tSpan)*plotW,y=v=>margin.top+(1-((v-min)/span))*plotH;
  const yVals=Array.from({length:5},(_,i)=>min+span*(i/4));let xDates;
  if(Array.isArray(xTicks)&&xTicks.length)xDates=xTicks;else if(dates.length<=4)xDates=dates;else xDates=[...new Set([dates[0],dates[Math.floor((dates.length-1)/3)],dates[Math.floor((dates.length-1)*2/3)],dates.at(-1)])];
  const gridY=yVals.map(v=>`<g><line x1="${margin.left}" y1="${y(v)}" x2="${width-margin.right}" y2="${y(v)}" stroke="rgba(255,255,255,.08)" stroke-width="1"/><text x="${margin.left-8}" y="${y(v)+4}" fill="rgba(220,232,255,.82)" font-size="10" text-anchor="end">${yTickFormatter(round(v,1))}</text></g>`).join('');
  const gridX=xDates.map(d=>`<g><line x1="${x(d)}" y1="${margin.top}" x2="${x(d)}" y2="${height-margin.bottom}" stroke="rgba(255,255,255,.05)" stroke-width="1"/><text x="${x(d)}" y="${height-35}" fill="rgba(220,232,255,.74)" font-size="10" text-anchor="middle">${shortDateLabel(d)}</text></g>`).join('');
  const seriesSvg=(series||[]).map(s=>{const pts=(s.points||[]).map(p=>`${x(p.date)},${y(p.value)}`).join(' ');if(!pts)return'';const circles=(s.points||[]).map(p=>`<circle cx="${x(p.date)}" cy="${y(p.value)}" r="2.7" fill="${s.color}" opacity="${s.dash?.82:1}"/>`).join('');return `<g><polyline points="${pts}" fill="none" stroke="${s.color}" stroke-width="${s.strokeWidth||3}" stroke-linecap="round" stroke-linejoin="round" ${s.dash?`stroke-dasharray="${s.dash}" opacity=".9"`:''}/>${circles}</g>`}).join('');
  const items=legend.length?legend:(series||[]).map(s=>({label:s.label,color:s.color,dash:s.dash||''})),slot=plotW/Math.max(1,items.length);
  const legendSvg=items.map((item,i)=>{const lx=margin.left+i*slot,ly=height-10;return `<g transform="translate(${lx},${ly})"><line x1="0" y1="0" x2="15" y2="0" stroke="${item.color}" stroke-width="2.5" ${item.dash?`stroke-dasharray="${item.dash}"`:''}/><text x="20" y="4" fill="rgba(235,243,255,.78)" font-size="9.2">${item.label}</text></g>`}).join('');
  return `<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" aria-label="Trend chart"><text x="${margin.left}" y="12" fill="rgba(220,232,255,.72)" font-size="10">${yLabel}</text>${gridY}${gridX}<line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height-margin.bottom}" stroke="rgba(255,255,255,.16)" stroke-width="1.2"/><line x1="${margin.left}" y1="${height-margin.bottom}" x2="${width-margin.right}" y2="${height-margin.bottom}" stroke="rgba(255,255,255,.16)" stroke-width="1.2"/>${seriesSvg}${legendSvg}</svg>`;
};



