// v4.0.16 · HARD HISTORY CAP
// Final render-time enforcement so Progress can never show more than five
// workout cards or five weekly review cards. "See all" opens the full history.
// ============================================================================
function ensureHistorySeeAllAfter(container,kind,total){
  if(!container||Number(total)<=5)return;
  const next=container.nextElementSibling;
  if(next?.classList?.contains('history-see-all'))return;
  const button=document.createElement('button');
  button.type='button';
  button.className='btn secondary history-see-all';
  button.textContent=kind==='workout'?`See all ${total} workouts ›`:`See all ${total} reviews ›`;
  button.onclick=kind==='workout'?openAllWorkoutHistory:openAllWeeklyReviews;
  container.insertAdjacentElement('afterend',button);
}
function enforceProgressHistoryCap(){
  const root=document.getElementById('progress');if(!root)return;
  const workoutContainer=root.querySelector('.workout-history');
  if(workoutContainer){
    const cards=[...workoutContainer.querySelectorAll(':scope > .workout-history-card')];
    cards.forEach((card,i)=>{card.style.display=i<5?'':'none'});
    root.querySelectorAll('.history-see-all[data-kind="workout"]').forEach(x=>x.remove());
    if(cards.length>5){
      const b=document.createElement('button');b.type='button';b.className='btn secondary history-see-all';b.dataset.kind='workout';b.textContent=`See all ${cards.length} workouts ›`;b.onclick=openAllWorkoutHistory;workoutContainer.insertAdjacentElement('afterend',b);
    }
  }
  const reviewContainer=root.querySelector('.weekly-review-history');
  if(reviewContainer){
    const cards=[...reviewContainer.querySelectorAll(':scope > .weekly-review-card')];
    cards.forEach((card,i)=>{card.style.display=i<5?'':'none'});
    root.querySelectorAll('.history-see-all[data-kind="review"]').forEach(x=>x.remove());
    if(cards.length>5){
      const b=document.createElement('button');b.type='button';b.className='btn secondary history-see-all';b.dataset.kind='review';b.textContent=`See all ${cards.length} reviews ›`;b.onclick=openAllWeeklyReviews;reviewContainer.insertAdjacentElement('afterend',b);
    }
  }
  // Keep section summaries truthful even if an older render function built the markup.
  const sections=[...root.querySelectorAll('.section')];
  const workoutSection=sections.find(s=>/Workout history/i.test(s.textContent||''));
  if(workoutSection){const sm=workoutSection.querySelector('.small');const total=(progress?.workoutLogs||[]).length;if(sm)sm.textContent=`Showing ${Math.min(5,total)} of ${total}`;}
  const reviewSection=sections.find(s=>/Weekly reviews/i.test(s.textContent||''));
  if(reviewSection){const sm=reviewSection.querySelector('.small');const total=(progress?.weeklyCheckins||[]).length;if(sm)sm.textContent=`Showing ${Math.min(5,total)} of ${total}`;}
}
