  if(planned&&workouts<planned)advice.push(`${workouts}/${planned} planned sessions were logged in the last 7 days. Get the remaining work in before adding more volume.`);else if(planned)advice.push(`Training consistency is on target at ${workouts} logged session${workouts===1?'':'s'} in the last 7 days.`);
