function gfMountSetupAlertForCurrentTab(){
  const alertBtn=document.getElementById('gfProfileSetupAlert');
  const actions=document.getElementById('gfTopbarActions');
  const profileBtn=document.getElementById('profileMenuButton');
  if(!alertBtn)return;
  const coachHome=document.body.classList.contains('coach-home-active');
  if(coachHome){
    if(alertBtn.parentElement!==document.body)document.body.appendChild(alertBtn);
  }else if(actions){
    if(alertBtn.parentElement!==actions)actions.insertBefore(alertBtn,profileBtn||actions.firstChild);
    // Clear any stale inline positioning left by older builds.
    alertBtn.style.removeProperty('top');
    alertBtn.style.removeProperty('right');
    alertBtn.style.removeProperty('left');
    alertBtn.style.removeProperty('bottom');
    alertBtn.style.removeProperty('width');
    alertBtn.style.removeProperty('height');
  }
}
const _gfUpdateProfileSetupAlertV418=updateProfileSetupAlert;
updateProfileSetupAlert=function(){
  const result=_gfUpdateProfileSetupAlertV418.apply(this,arguments);
  requestAnimationFrame(gfMountSetupAlertForCurrentTab);
  return result;
};
const _gfShowTabV418=showTab;
showTab=function(tab){
  const result=_gfShowTabV418.apply(this,arguments);
  requestAnimationFrame(gfMountSetupAlertForCurrentTab);
  setTimeout(gfMountSetupAlertForCurrentTab,60);
  return result;
};
window.addEventListener('orientationchange',()=>setTimeout(gfMountSetupAlertForCurrentTab,120),{passive:true});
