  const rows=[...(progress?.weeklyCheckins||[])].filter(x=>x?.analysis?.scores&&x.id!==checkin.id&&String(x.date||'')<String(checkin.date||'')).sort((x,y)=>String(y.date||'').localeCompare(String(x.date||''))),prev=rows[0]?.analysis||null;
  const out=[];const mass=gfAnalysisMassScore(a),pm=gfAnalysisMassScore(prev);if(Number.isFinite(mass)&&Number.isFinite(pm)){const d=mass-pm;out.push(`<div class="analysis-observation"><b>Mass / fullness signal</b><br>${Math.abs(d)<1.2?'Upper-body silhouette is broadly stable':d>0?`Upper-body fullness is up ${gfFmtDelta(d,' pts')} versus the previous check-in`:`Upper-body fullness is down ${Math.abs(d).toFixed(1)} pts versus the previous check-in`}. This is a visual proportion signal, not a direct muscle-mass measurement.</div>`)}
  const def=gfAnalysisDefinition(a),pdef=gfAnalysisDefinition(prev);if(Number.isFinite(def)){let text=`Definition signal ${Math.round(def)}/100`;if(Number.isFinite(pdef)){const d=def-pdef;text+=Math.abs(d)<3?' · broadly unchanged':d>0?` · clearer by ${Math.round(d)} points`:` · softer by ${Math.round(Math.abs(d))} points`}out.push(`<div class="analysis-observation"><b>Definition</b><br>${text}. Lighting, distance and pump can affect this, so Hercules only treats repeated changes as meaningful.</div>`)}
