  function band(y0,y1,x0=.25,x1=.75){let sum=0,n=0,mean=0,m2=0;const ys=Math.max(1,Math.floor(h*y0)),ye=Math.min(h-2,Math.floor(h*y1)),xs=Math.max(1,Math.floor(w*x0)),xe=Math.min(w-2,Math.floor(w*x1)),step=Math.max(1,Math.floor(Math.min(w,h)/130));for(let y=ys;y<=ye;y+=step)for(let x=xs;x<=xe;x+=step){const i=(y*w+x)*4,gray=.299*d[i]+.587*d[i+1]+.114*d[i+2],ir=(y*w+x+step)*4,id=((Math.min(h-1,y+step))*w+x)*4,gr=.299*d[ir]+.587*d[ir+1]+.114*d[ir+2],gd=.299*d[id]+.587*d[id+1]+.114*d[id+2],edge=Math.abs(gray-gr)+Math.abs(gray-gd);sum+=edge;n++;const delta=gray-mean;mean+=delta/n;m2+=delta*(gray-mean)}return {edge:n?sum/n:0,sd:n>1?Math.sqrt(m2/(n-1)):0}}
  const upper=band(.20,.58),lower=band(.60,.92,.28,.72);const definition=clamp((upper.edge*.55+upper.sd*.45)*1.35,0,100),lowerDetail=clamp((lower.edge*.55+lower.sd*.45)*1.35,0,100);return {definitionIndex:round(definition,1),upperDetail:round(definition,1),lowerDetail:round(lowerDetail,1)}
