  if(prevScores){const deltas=keys.map(k=>({k,d:(Number(scores[k])||0)-(Number(prevScores[k])||0),s:Number(scores[k])||0}));developing=[...deltas].sort((a,b)=>b.d-a.d).filter(x=>x.d>=1.1).slice(0,2).map(x=>x.k);if(!developing.length&&deltas.length)developing=[deltas.sort((a,b)=>b.d-a.d)[0].k];priority=[...deltas].sort((a,b)=>(a.s+physiqueDeltaWeight(a.d))-(b.s+physiqueDeltaWeight(b.d))).map(x=>x.k).filter(k=>!developing.includes(k)).slice(0,2)}else{const ranked=keys.map(k=>({k,s:Number(scores[k])||0})).sort((a,b)=>b.s-a.s);developing=ranked.slice(0,2).map(x=>x.k);priority=ranked.slice(-2).reverse().filter(x=>!developing.includes(x.k)).map(x=>x.k)}
  maintain=keys.filter(k=>!developing.includes(k)&&!priority.includes(k)).slice(0,2);const dKey=developing[0]||'shoulders',pKey=priority[0]||'chest',d=regionLabel(dKey),p=regionLabel(pKey),trainingMap={chest:'Bias progressive incline/flat pressing and controlled chest isolation while keeping shoulder fatigue in check.',lats:'Bias pulldowns or pull-ups plus stable rows, with progression tracked separately for width and thickness.',shoulders:'Emphasise lateral and rear-delt progression while keeping pressing volume recoverable.',arms:'Add a modest amount of direct biceps and triceps work and progress it like the compound lifts.',legs:'Use consistent squat/hinge plus isolation progression once leg visibility is reliable.'};
