function gfWorkoutDurationMinutes(w){
  const a=new Date(w?.startedAt||0).getTime(),b=new Date(w?.completedAt||0).getTime();
  if(!a||!b||b<a)return 0;
  return Math.max(1,Math.round((b-a)/60000));
}
function gfCompletedSessionBefore(w){
  return [...(progress?.workoutLogs||[])].filter(x=>x&&x.id!==w.id&&x.completed!==false&&x.sessionId===w.sessionId&&String(x.completedAt||x.date||'')<String(w.completedAt||w.date||'')).sort((a,b)=>String(b.completedAt||b.date||'').localeCompare(String(a.completedAt||a.date||'')))[0]||null;
}
function gfWorkoutAvgRIR(w){const vals=(w?.setEntries||[]).map(x=>Number(x.rir)).filter(Number.isFinite);return vals.length?gfArrayMean(vals):null}
function gfWorkoutBestByExercise(w){
  const out={};(w?.setEntries||[]).forEach(x=>{const key=x.exerciseKey||x.exerciseName||'exercise',score=e1RM(x.weightKg,x.reps);if(score>(out[key]?.score||0))out[key]={score,exerciseName:x.exerciseName||key,weightKg:Number(x.weightKg)||0,reps:Number(x.reps)||0}});return out;
}
function gfPostWorkoutData(w){
  const s=plan?.training?.sessions?.find(x=>x.id===w.sessionId),prev=gfCompletedSessionBefore(w),sets=(w.setEntries||[]).length,planned=(s?.exercises||[]).reduce((n,e)=>n+(Number(e.sets)||0),0),volume=workoutVolume(w),prevVolume=prev?workoutVolume(prev):0,duration=gfWorkoutDurationMinutes(w),avgRir=gfWorkoutAvgRIR(w),currentBest=gfWorkoutBestByExercise(w),prevBest=prev?gfWorkoutBestByExercise(prev):{},prs=[];
  Object.entries(currentBest).forEach(([k,v])=>{const p=prevBest[k];if(p&&v.score>p.score*1.015)prs.push({name:v.exerciseName,change:((v.score/p.score)-1)*100})});
  const completion=planned?clamp((sets/planned)*100,0,140):100,volChange=prevVolume>0?((volume/prevVolume)-1)*100:null;
  const notes=[];
  if(prev&&Number.isFinite(volChange)){if(volChange>7)notes.push({title:'Work capacity',text:`Total logged volume increased by about ${Math.round(volChange)}% versus the last ${s?.name||'session'}.`});else if(volChange<-10)notes.push({title:'Volume lower',text:`Logged volume was about ${Math.round(Math.abs(volChange))}% lower than last time. That can be fine if technique, fatigue or exercise selection changed.`});else notes.push({title:'Consistency',text:'Total session volume was close to the previous workout, giving a useful like-for-like comparison.'})}
  if(prs.length)notes.push({title:'Progression',text:`${prs.length} exercise${prs.length===1?'':'s'} improved estimated strength: ${prs.slice(0,3).map(x=>x.name).join(', ')}.`});
  if(completion<85)notes.push({title:'Completion',text:`You completed about ${Math.round(completion)}% of the planned working sets. Hercules will treat this as a partial session rather than a failed one.`});
  else notes.push({title:'Completion',text:`You completed ${sets} of ${planned||sets} planned working sets.`});
  let advice='';
  if(Number.isFinite(avgRir)&&avgRir<0.8)advice='A lot of work was very close to failure. Keep the next session controlled: prioritise clean reps and avoid adding load everywhere at once.';
  else if(Number.isFinite(avgRir)&&avgRir>=2.5&&completion>=90)advice='You finished with plenty in reserve. If technique was solid and you reached the top of the rep ranges, progress one or two key lifts next time rather than increasing everything.';
  else if(prs.length>=2)advice='This was a productive progression session. Keep the same execution standard and only increase load where the full rep target is repeatable.';
  else if(completion<80)advice='Do not compensate by cramming missed sets into the next workout. Resume the normal plan and look for the reason the session ran short: time, fatigue or exercise difficulty.';
  else advice='Good baseline session. Repeat the same movements with clean technique and look for one small improvement next time: an extra rep, slightly better control, or a modest load increase.';
  return {session:s,prev,sets,planned,volume,prevVolume,duration,avgRir,completion,volChange,prs,notes,advice};
}
